<?php require __DIR__.'/ui.php';auth();$p=db();if(isset($_GET['read']))$p->prepare("UPDATE notifications SET is_read=1 WHERE id=?")->execute([(int)$_GET['read']]);$rows=$p->query("SELECT * FROM notifications ORDER BY is_read,created_at DESC LIMIT 200")->fetchAll();page_head('Central de notificações');?><div class="card"><div class="table"><table><tr><th></th><th>Alerta</th><th>Mensagem</th><th>Data</th></tr><?php foreach($rows as $x):?><tr><td><?=$x['is_read']?'✓':'●'?></td><td><b><?=e($x['title'])?></b></td><td><?=e($x['message'])?></td><td><?=e($x['created_at'])?> <?php if(!$x['is_read']):?><a href="?read=<?=$x['id']?>">Marcar lida</a><?php endif;?></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>